#!/usr/bin/env python3
"""Generate IPCC AR6 poster via HTML + Playwright screenshot."""

import math

# A0 at 100 DPI
DPI = 100
A0_W_MM = 841
A0_H_MM = 1189
W_PX = int(A0_W_MM / 25.4 * DPI)   # ~3311
H_PX = int(A0_H_MM / 25.4 * DPI)   # ~4681

# Scale factor: our HTML is designed for a 1200px wide viewport at A0 ratio
# We render at W_PX and use CSS that scales accordingly
SCALE = W_PX / 1200.0  # ~2.76

css = f"""
* {{ margin: 0; padding: 0; box-sizing: border-box; }}
body {{
  width: 1200px;
  height: {1200 * A0_H_MM / A0_W_MM:.0f}px;
  font-family: 'Liberation Sans', 'DejaVu Sans', Arial, sans-serif;
  background: #060d17;
  color: #eef2f6;
  overflow: hidden;
  position: relative;
}}

/* ── Header ── */
.header {{
  position: absolute; top: 28px; left: 30px; right: 30px; height: 72px;
  background: #0d1a2d; border-radius: 12px;
  display: flex; align-items: center; padding: 0 30px;
}}
.badge {{
  background: #f0a500; color: #060d17; font-weight: 900; font-size: 17px;
  padding: 8px 18px; border-radius: 8px; letter-spacing: 0.5px;
  white-space: nowrap; margin-right: 28px;
}}
.header-title {{
  font-weight: 700; font-size: 30px; color: #eef2f6; line-height: 1.15;
}}
.header-venue {{
  font-size: 13px; color: #8899aa; margin-top: 2px;
}}

/* ── Metrics Banner ── */
.metrics {{
  position: absolute; top: 126px; left: 30px; right: 30px; height: 190px;
  background: #0d1a2d; border-radius: 12px;
  display: flex; align-items: center; justify-content: space-around;
  padding: 10px 0;
}}
.metric {{
  text-align: center; flex: 1; position: relative;
}}
.metric::after {{
  content: '';
  position: absolute; right: 0; top: 15%; height: 70%;
  width: 1px; background: #1e3350;
}}
.metric:last-child::after {{ display: none; }}
.metric-value {{
  font-size: 52px; font-weight: 900; line-height: 1.05; letter-spacing: -0.5px;
}}
.metric-label {{
  font-size: 12px; color: #8899aa; line-height: 1.3; margin-top: 4px;
  max-width: 130px; margin-left: auto; margin-right: auto;
}}
.c-vermilion {{ color: #e64539; }}
.c-amber {{ color: #f0a500; }}
.c-teal {{ color: #2a9d8f; }}

/* ── Section shared ── */
.section-card {{
  position: absolute; left: 30px; right: 30px;
  background: #0d1a2d; border-radius: 12px; padding: 28px 32px;
}}
.section-title {{
  font-size: 28px; font-weight: 700; color: #eef2f6; margin-bottom: 6px;
}}
.section-rule {{
  height: 3px; width: 52px; border-radius: 2px; margin-bottom: 18px;
}}
.rule-amber {{ background: #f0a500; }}
.rule-teal {{ background: #2a9d8f; }}
.rule-vermilion {{ background: #e64539; }}

/* ── Section 1: Observed Changes ── */
.sec1 {{ top: 342px; height: 310px; }}
.sec1-grid {{ display: flex; gap: 40px; }}
.sec1-left {{ flex: 1; }}
.sec1-right {{ flex: 1; }}
.sec1-body {{ font-size: 15px; line-height: 1.55; color: #eef2f6; }}
.sec1-body .bold-lead {{ font-weight: 700; display: block; margin-bottom: 6px; }}
.indicator-table {{ width: 100%; border-collapse: collapse; }}
.indicator-table td {{
  padding: 7px 0; font-size: 14px; border-bottom: 1px solid #1e3350;
  vertical-align: top; line-height: 1.4;
}}
.indicator-table td:first-child {{ color: #8899aa; padding-right: 12px; }}
.indicator-table td:last-child {{ color: #eef2f6; font-weight: 700; text-align: right; white-space: nowrap; }}

/* ── Section 2: Future Projections ── */
.sec2 {{ top: 678px; height: 300px; }}
.sec2-grid {{ display: flex; gap: 40px; }}
.sec2-left {{ flex: 0 0 460px; }}
.sec2-right {{ flex: 1; }}
.chart-container {{ display: flex; align-items: flex-end; justify-content: space-around; height: 200px; padding: 0 8px; border-bottom: 1px solid #1e3350; position: relative; }}
.chart-bar-wrapper {{ display: flex; flex-direction: column; align-items: center; flex: 1; }}
.chart-bar {{
  width: 50px; border-radius: 6px 6px 0 0; transition: none;
  position: relative;
}}
.chart-bar-val {{
  font-size: 14px; font-weight: 700; color: #eef2f6;
  margin-bottom: 6px;
}}
.chart-bar-label {{
  font-size: 10px; color: #8899aa; text-align: center; line-height: 1.3;
  margin-top: 8px;
}}
.chart-ref-line {{
  position: absolute; left: 8px; right: 8px; border-top: 1px dashed rgba(255,255,255,0.25);
}}
.chart-ref-label {{
  position: absolute; right: 8px; font-size: 10px; color: rgba(255,255,255,0.4);
  transform: translateY(-50%);
}}
.sec2-body {{ font-size: 15px; line-height: 1.55; color: #eef2f6; }}

/* ── Section 3: Risks & Impacts ── */
.sec3 {{ top: 1004px; height: 210px; }}
.risk-grid {{ display: flex; gap: 30px; }}
.risk-col {{ flex: 1; }}
.risk-col-header {{ display: flex; align-items: center; gap: 10px; margin-bottom: 8px; }}
.risk-dot {{
  width: 14px; height: 14px; border-radius: 50%; background: #e64539;
  flex-shrink: 0;
}}
.risk-col-title {{ font-size: 16px; font-weight: 700; color: #f0a500; }}
.risk-col-body {{ font-size: 13px; color: #8899aa; line-height: 1.5; padding-left: 24px; }}
.risk-biodiv {{
  font-size: 14px; font-weight: 700; color: #eef2f6;
  margin-top: 14px; padding-top: 12px; border-top: 1px solid #1e3350;
}}

/* ── Section 4: Mitigation ── */
.sec4 {{ top: 1240px; height: 210px; }}
.mit-grid {{ display: flex; gap: 40px; }}
.mit-col {{ flex: 1; }}
.mit-col-title {{ font-size: 17px; font-weight: 700; margin-bottom: 10px; }}
.mit-col-body {{ font-size: 14px; color: #8899aa; line-height: 1.65; }}
.mit-levers {{
  font-size: 12px; color: #5a6d80; margin-top: 20px;
  padding-top: 14px; border-top: 1px solid #1e3350;
}}

/* ── Section 5: Narrowing Window ── */
.sec5 {{
  top: 1476px; height: 95px; background: #150a14;
  border: 1px solid #2a1018;
}}
.sec5-body {{ font-size: 15px; font-weight: 700; color: #eef2f6; line-height: 1.4; }}
.sec5-urgent {{ font-size: 17px; font-weight: 700; color: #e64539; margin-top: 6px; }}

/* ── Footer ── */
.footer {{
  position: absolute; bottom: 34px; left: 30px; right: 30px; height: 30px;
  display: flex; justify-content: space-between; align-items: center;
  font-size: 10px; color: #5a6d80;
}}
.footer-right {{ font-weight: 700; }}
"""

html = f"""<!DOCTYPE html>
<html><head><meta charset="utf-8"><style>{css}</style></head><body>

<!-- HEADER -->
<div class="header">
  <div class="badge">IPCC AR6</div>
  <div>
    <div class="header-title">Climate Change 2023: Key Findings from the IPCC Synthesis Report</div>
    <div class="header-venue">AR6 Synthesis Report Dissemination — Climate Science Conference &nbsp;|&nbsp; 2023</div>
  </div>
</div>

<!-- METRICS BANNER -->
<div class="metrics">
  <div class="metric">
    <div class="metric-value c-vermilion">+1.1°C</div>
    <div class="metric-label">Global surface temp. increase<br>2011–2020 vs 1850–1900</div>
  </div>
  <div class="metric">
    <div class="metric-value c-amber">410 ppm</div>
    <div class="metric-label">Atmospheric CO₂<br>concentration in 2019</div>
  </div>
  <div class="metric">
    <div class="metric-value c-amber">~59 GtCO₂e</div>
    <div class="metric-label">Global GHG emissions<br>in 2019</div>
  </div>
  <div class="metric">
    <div class="metric-value c-teal">~500 GtCO₂</div>
    <div class="metric-label">Remaining carbon budget<br>for 1.5°C (50% likelihood)</div>
  </div>
  <div class="metric">
    <div class="metric-value c-vermilion">−43%</div>
    <div class="metric-label">Required GHG reduction<br>by 2030 for 1.5°C pathway</div>
  </div>
  <div class="metric">
    <div class="metric-value c-amber">+0.20 m</div>
    <div class="metric-label">Sea level rise<br>1901–2018</div>
  </div>
  <div class="metric">
    <div class="metric-value c-vermilion">3.3–3.6B</div>
    <div class="metric-label">People exposed to<br>severe climate hazards</div>
  </div>
</div>

<!-- SECTION 1: Observed Changes -->
<div class="section-card sec1">
  <div class="section-title">Observed Changes and Current State</div>
  <div class="section-rule rule-amber"></div>
  <div class="sec1-grid">
    <div class="sec1-left">
      <div class="sec1-body">
        <span class="bold-lead">Human influence has unequivocally warmed the atmosphere, ocean, and land.</span>
        Global surface temperature rose by 1.1°C between 2011–2020 relative to the pre-industrial baseline of 1850–1900. This warming is unprecedented in more than 2,000 years of Earth's climate history.
      </div>
      <div class="sec1-body" style="margin-top:14px;">
        Every region on Earth now experiences increases in the frequency and intensity of extreme weather events — heatwaves, heavy precipitation, droughts, and tropical cyclones — with clear attribution to human influence.
      </div>
    </div>
    <div class="sec1-right">
      <table class="indicator-table">
        <tr><td>Arctic sea ice decline (Sep, 1979–2020)</td><td>~40% area loss</td></tr>
        <tr><td>Sea level rise (1901–2018)</td><td>~0.20 m</td></tr>
        <tr><td>Atmospheric CO₂ (2019)</td><td>410 ppm — highest in ≥2M years</td></tr>
        <tr><td>Global GHG emissions (2019)</td><td>~59 GtCO₂-equivalent</td></tr>
        <tr><td>Ocean heat content increase</td><td>Unprecedented since at least 1970</td></tr>
      </table>
    </div>
  </div>
</div>

<!-- SECTION 2: Future Projections -->
<div class="section-card sec2">
  <div class="section-title">Future Projections Under Different Scenarios</div>
  <div class="section-rule rule-amber"></div>
  <div class="sec2-grid">
    <div class="sec2-left">
      <div class="chart-container" style="height:195px;">
        <div class="chart-ref-line" style="bottom:51.7%;"></div>
        <div class="chart-ref-label" style="bottom:51.7%;">1.5°C threshold</div>
        <div class="chart-ref-line" style="bottom:34.5%; border-style:dotted;"></div>
        <div class="chart-ref-label" style="bottom:34.5%;">2.0°C threshold</div>
        <div class="chart-bar-wrapper">
          <div class="chart-bar-val">1.4°C</div>
          <div class="chart-bar" style="height:70px;background:#2a9d8f;"></div>
          <div class="chart-bar-label">SSP1-1.9<br>Very low</div>
        </div>
        <div class="chart-bar-wrapper">
          <div class="chart-bar-val">1.8°C</div>
          <div class="chart-bar" style="height:89px;background:#4aad6f;"></div>
          <div class="chart-bar-label">SSP1-2.6<br>Low</div>
        </div>
        <div class="chart-bar-wrapper">
          <div class="chart-bar-val">2.7°C</div>
          <div class="chart-bar" style="height:130px;background:#f0a500;"></div>
          <div class="chart-bar-label">SSP2-4.5<br>Intermediate</div>
        </div>
        <div class="chart-bar-wrapper">
          <div class="chart-bar-val">3.6°C</div>
          <div class="chart-bar" style="height:173px;background:#e67329;"></div>
          <div class="chart-bar-label">SSP3-7.0<br>High</div>
        </div>
        <div class="chart-bar-wrapper">
          <div class="chart-bar-val">4.4°C</div>
          <div class="chart-bar" style="height:210px;background:#e64539;"></div>
          <div class="chart-bar-label">SSP5-8.5<br>Very high</div>
        </div>
      </div>
    </div>
    <div class="sec2-right">
      <div class="sec2-body">
        <strong style="color:#f0a500;">Projected Warming by 2100 (Best Estimates)</strong><br><br>
        Under the very low emissions scenario (SSP1-1.9), global warming is likely to reach 1.5°C in the near term before declining slightly.<br><br>
        Under the very high emissions scenario (SSP5-8.5), warming could exceed 4.4°C — with catastrophic consequences for ecosystems and human societies.<br><br>
        Sea level is projected to rise by 0.28–0.55 m under SSP1-1.9 and 0.63–1.01 m under SSP5-8.5 by 2100, with continued rise for centuries to millennia regardless of pathway.
      </div>
    </div>
  </div>
</div>

<!-- SECTION 3: Risks & Impacts -->
<div class="section-card sec3">
  <div class="section-title">Risks, Vulnerabilities, and Cascading Impacts</div>
  <div class="section-rule rule-amber"></div>
  <div class="risk-grid">
    <div class="risk-col">
      <div class="risk-col-header"><div class="risk-dot"></div><div class="risk-col-title">Food Security</div></div>
      <div class="risk-col-body">Crop yield growth rates have slowed in many regions. Fisheries productivity is declining in tropical zones.</div>
    </div>
    <div class="risk-col">
      <div class="risk-col-header"><div class="risk-dot"></div><div class="risk-col-title">Water Stress</div></div>
      <div class="risk-col-body">Over half the world's population experiences severe water scarcity for at least one month per year.</div>
    </div>
    <div class="risk-col">
      <div class="risk-col-header"><div class="risk-dot"></div><div class="risk-col-title">Health & Disease</div></div>
      <div class="risk-col-body">Heat-related mortality and vector-borne disease ranges are expanding globally in all regions.</div>
    </div>
  </div>
  <div class="risk-biodiv">
    Biodiversity: Up to 14% of terrestrial species face very high extinction risk at 1.5°C — rising sharply at higher warming levels.
  </div>
</div>

<!-- SECTION 4: Mitigation -->
<div class="section-card sec4">
  <div class="section-title">Mitigation and Adaptation Pathways</div>
  <div class="section-rule rule-teal"></div>
  <div class="mit-grid">
    <div class="mit-col">
      <div class="mit-col-title" style="color:#2a9d8f;">1.5°C Pathway (No or Limited Overshoot)</div>
      <div class="mit-col-body">
        43% reduction in global GHG emissions below 2019 levels by 2030<br>
        Net zero CO₂ emissions by around 2050<br>
        Remaining carbon budget: ~500 GtCO₂ (50% likelihood)
      </div>
    </div>
    <div class="mit-col">
      <div class="mit-col-title" style="color:#8899aa;">2°C Pathway</div>
      <div class="mit-col-body">
        27% reduction below 2019 levels by 2030<br>
        Net zero CO₂ by around 2070<br>
        Higher adaptation costs and greater residual risks
      </div>
    </div>
  </div>
  <div class="mit-levers">
    Key levers: &nbsp;Rapid energy decarbonization &nbsp;·&nbsp; Transport electrification &nbsp;·&nbsp; Demand-side efficiency &nbsp;·&nbsp; Carbon sink restoration
  </div>
</div>

<!-- SECTION 5: Narrowing Window -->
<div class="section-card sec5">
  <div class="section-title">The Narrowing Window for Action</div>
  <div class="section-rule rule-vermilion"></div>
  <div class="sec5-body">
    Choices made in this decade will determine whether warming can be held to 1.5°C or 2°C. Delayed action increases costs, locks in high-carbon infrastructure, and reduces the feasibility of limiting warming. Climate finance flows fall short of needs by a factor of 3 to 6 for adaptation alone.
  </div>
  <div class="sec5-urgent">
    Immediate, deep, and sustained emissions reductions across all sectors are essential to secure a liveable and sustainable future.
  </div>
</div>

<!-- FOOTER -->
<div class="footer">
  <div>Source: IPCC, 2023. AR6 Synthesis Report: Climate Change 2023. Intergovernmental Panel on Climate Change.</div>
  <div class="footer-right">IPCC AR6 SYNTHESIS REPORT &nbsp;|&nbsp; CLIMATE CHANGE 2023</div>
</div>

</body></html>
"""

import tempfile, os

html_path = '/tmp/poster.html'
with open(html_path, 'w') as f:
    f.write(html)

from playwright.sync_api import sync_playwright

with sync_playwright() as p:
    browser = p.chromium.launch()
    page = browser.new_page(viewport={"width": W_PX, "height": H_PX})
    page.goto(f'file://{html_path}')
    # Wait for fonts to load
    page.wait_for_timeout(1000)
    page.screenshot(path='/app/output/final_poster.png', full_page=False)
    browser.close()

print(f'Poster saved to /app/output/final_poster.png ({W_PX}×{H_PX} px, {DPI} DPI)')

